// ---------- Uso ----------
const idiomaGuardado = () => { try { const v = localStorage.getItem("cw_idioma"); return v ? JSON.parse(v) : null; } catch (e) { return null; } };
// ?lang=en en la dirección fuerza el idioma sin preguntar (lo usa la landing page)
const IDIOMA_URL = (() => { try { const l = new URLSearchParams(location.search).get("lang"); return IDIOMAS.some(i => i.c === l) ? l : null; } catch (e) { return null; } })();
let IDIOMA = IDIOMA_URL || idiomaGuardado() || "es";
// t("clave", { u: "kn" }) → texto en el idioma elegido (si falta, en español)
function t(k, vars) {
  let s = (TXT[IDIOMA] && TXT[IDIOMA][k]) ?? TXT.es[k] ?? k;
  if (vars) Object.entries(vars).forEach(([a, b]) => { s = s.split("{" + a + "}").join(b); });
  return s;
}
const localeIdioma = () => (IDIOMAS.find(i => i.c === IDIOMA) || IDIOMAS[0]).loc;
// Dirección guardada en español (N, NE, SO, O…) → en el idioma elegido
const dirIdioma = (d) => { const i = PUNTOS_IDIOMA.es.indexOf(d); return i >= 0 ? PUNTOS_IDIOMA[IDIOMA][i] : d; };
// Idioma del navegador si es uno de los nuestros (para la primera vez)
const idiomaNavegador = () => { const l = (navigator.language || "es").slice(0, 2).toLowerCase(); return IDIOMAS.some(i => i.c === l) ? l : "es"; };
